const items = $input.all();
if (items.length === 0) {
  return [{ json: { prompt: '', count: 0, empty: true } }];
}
const lines = items.map((it, i) => {
  const j = it.json;
  const from = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || j.From || j.from || 'unknown';
  const subj = j.subject || j.Subject || '(no subject)';
  const snip = String(j.snippet || j.textPlain || '').replace(/\s+/g, ' ').slice(0, 220);
  return `${i + 1}. FROM: ${from} | SUBJECT: ${subj}
   ${snip}`;
});
const prompt = `You are an email triage assistant. Below are emails from the last 24 hours.

EMAILS:
${lines.join('
')}

Write a concise markdown brief with exactly these sections:
## Action needed
- one bullet per email that needs a reply, decision, or task (say what, from whom, and any deadline)
## Waiting / FYI
- bullets for things to know but not act on
## Suggested top 3 todos today
- numbered, most important first

Rules: use ONLY information from the emails; if a section is empty write 'none'; no preamble, start directly with the first heading.`;
return [{ json: { prompt, count: items.length, empty: false } }];

const resp = ($json.response || '(model returned nothing)').trim();
const count = $('Compact emails').first().json.count;
const date = new Date().toISOString().slice(0, 10);
const md = `---
type: digest
ai: true
source: n8n email-daily-brief
created: ${date}
tags: [email, brief]
---

# 📧 Email brief — ${date}

_${count} email(s) scanned in the last 24h._ 🤖

${resp}
`;
return [{ json: { md, filename: `email-brief-${date}.md` } }];
